{
  "name": "pi-cn-free-model-providers",
  "version": "1.0.31",
  "description": "pi (AI coding agent CLI) extension for mainland-China users: curated access to free-first model providers including OpenCode Zen, SenseNova, SiliconFlow, ModelScope, NVIDIA NIM, Cloudflare, and Agnes AI. Providers support Pi-managed auth.json credentials with environment-variable fallbacks.",
  "type": "module",
  "main": "pi-cn-free-model-providers-ext.mjs",
  "scripts": {
    "test": "node --test test/*.test.mjs",
    "check": "node --check pi-cn-free-model-providers-ext.mjs"
  },
  "files": [
    "pi-cn-free-model-providers-ext.mjs",
    "README.md",
    "test"
  ],
  "keywords": [
    "pi-package",
    "pi",
    "opencode",
    "zen",
    "deepseek",
    "free-models",
    "china",
    "mainland-china",
    "model-providers",
    "extension",
    "cli"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/pgciq/pi-cn-free-model-providers.git"
  },
  "bugs": {
    "url": "https://github.com/pgciq/pi-cn-free-model-providers/issues"
  },
  "homepage": "https://github.com/pgciq/pi-cn-free-model-providers#readme",
  "engines": {
    "node": ">=20.0.0"
  },
  "pi": {
    "extensions": [
      "pi-cn-free-model-providers-ext.mjs"
    ]
  }
}
